/* tempInqyDao1010 : 기안문 양식 목록 조회 */ SELECT T.TEMP_CD , T.TEMP_NM , T.TEMPTYPE_CD , T.REG_MAPPING_ID , T.DET_MAPPING_ID , T.DISP_ORDER , T.REMARK , '1' AS LV , 'Y' AS ISLEAF , COUNT(T.TEMP_CD) OVER() AS LIST_CNT , ROW_NUMBER() OVER(ORDER BY T.TEMP_CD ASC) AS NUM FROM TEMPLATE T WHERE 1=1
AND REGEXP_REPLACE(LOWER(T.TEMP_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
ORDER BY T.TEMP_CD ASC

mapper.update:
/* tempProcDao1010 : 기안문 양식 수정 처리 */
UPDATE TEMPLATE
	SET		TEMP_NM = #{tempNm, jdbcType=VARCHAR}
			,	TEMP_CONT = #{tempCont, jdbcType=VARCHAR}
			,	USE_YN = #{useYn, jdbcType=VARCHAR}
WHERE TEMP_CD = #{tempCd, jdbcType=VARCHAR}
